using System;
using System.Diagnostics;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
namespace StickyNotes;
public sealed class SettingsWindow:Window {
 readonly NotesApp app;readonly Border surface;readonly StackPanel body=new();readonly System.Collections.Generic.List<Button> themes=new();WindowRevealAnimation? animation;bool closing;
 public SettingsWindow(NotesApp app,WidgetWindow owner){this.app=app;Title="Configurações · Sticky Notes";Visuals.Base(this,owner.Width,400);ShowInTaskbar=Environment.GetCommandLineArgs().Contains("--inspect");Owner=owner;Topmost=owner.Topmost;surface=SuitePanels.Surface(this);var root=new DockPanel();surface.Child=root;
  var title=Visuals.Label("Configurações",20);title.FontWeight=FontWeights.SemiBold;var header=SuiteChrome.Header(title,Visuals.Icon("\uE8BB","Fechar configurações",()=>Dismiss()));DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);body.Margin=new Thickness(20,0,20,12);root.Children.Add(SuiteScroll.Wrap(new ScrollViewer{Content=body}));
  var appearance=Group("\uE790","Aparência e inicialização");var choices=new System.Windows.Controls.Primitives.UniformGrid{Columns=3};foreach(var option in new[]{("Sistema","Padrão"),("Escuro","Escuro"),("Claro","Claro")}){var choice=option;var button=Visuals.TextButton(choice.Item2,()=>{app.Store.Book.Theme=choice.Item1;app.Store.Save();app.ApplyTheme();});button.Tag=choice.Item1;button.Padding=new Thickness(4,7,4,7);button.FontSize=12;System.Windows.Automation.AutomationProperties.SetName(button,"Tema "+choice.Item2);themes.Add(button);choices.Children.Add(button);}appearance.Children.Add(choices);
  var startup=new CheckBox{Content=new TextBlock{Text="Iniciar com o Windows, apenas na bandeja",TextWrapping=TextWrapping.Wrap,FontSize=12},IsEnabled=false,Margin=new Thickness(0,8,0,8)};var startupStatus=Visuals.Label("",11);startupStatus.Visibility=Visibility.Collapsed;async System.Threading.Tasks.Task ReadStartup(){try{startup.IsChecked=await app.StartupEnabledAsync();startup.IsEnabled=string.Equals(app.DataRoot,NotesApp.DefaultRoot,StringComparison.OrdinalIgnoreCase);if(!startup.IsEnabled)startup.ToolTip="Sessão de teste: inicialização do Windows preservada.";}catch(Exception e){startupStatus.Text=e.Message;startupStatus.Visibility=Visibility.Visible;}}startup.Click+=async(_,_)=>{startup.IsEnabled=false;try{await app.SetStartup(startup.IsChecked==true);}catch(Exception e){startupStatus.Text=e.Message;startupStatus.Visibility=Visibility.Visible;}finally{await ReadStartup();}};appearance.Children.Add(startup);appearance.Children.Add(startupStatus);_=ReadStartup();
  var areas=Group("\uE8B7","Áreas da sua mesa");areas.Children.Add(Visuals.Label("Separe trabalho, ideias e assuntos pessoais. São grupos próprios do app.",12));var name=Visuals.Input("Nome da nova área");name.MaxLength=50;name.Padding=new Thickness(8);name.MinHeight=34;areas.Children.Add(name);areas.Children.Add(Visuals.TextButton("Criar área",()=>{var a=name.Text.Trim();if(a.Length==0){Visuals.Error("Dê à área um nome de 1 a 50 caracteres.");return;}if(app.Store.Book.Areas.Any(x=>x.Equals(a,StringComparison.CurrentCultureIgnoreCase))){Visuals.Error("Já existe uma área com esse nome.");return;}app.Store.Book.Areas.Add(a);app.Store.Save();app.SwitchArea(a);app.Widget.Refresh();name.Clear();}));
  var data=Group("\uE8F1","Dados e backup");data.Children.Add(Visuals.Label("Notas e imagens ficam neste computador, sem conta ou sincronização. A lixeira permite restaurar notas excluídas.",12));data.Children.Add(Visuals.TextButton("Exportar backup completo…",app.ExportBackup));data.Children.Add(Visuals.TextButton("Abrir pasta de dados",()=>Process.Start(new ProcessStartInfo(app.DataRoot){UseShellExecute=true})));
  var help=Group("\uE946","Atalhos e sobre");help.Children.Add(Visuals.Label("Ctrl+N · nova nota\nCtrl+, · configurações\nCtrl+B / Ctrl+I · formatação\nCtrl+V · colar texto ou imagem\nEsc · recolher a janela\nCtrl+Shift+H · ocultar todas as notas",12));help.Children.Add(Visuals.Label("Windows Sticky Notes "+Distribution.Version,11));help.Children.Add(Visuals.Label("50 cores · Normal, Pastel, Vivas, Neon e Terrosas. Arraste cada nota pela faixa superior para posicioná-la.",12));
  PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Escape){Dismiss();e.Handled=true;}};Closing+=(_,e)=>{if(!closing&&!app.Exiting){e.Cancel=true;Dismiss();}};Closed+=(_,_)=>animation?.Dispose();ApplyTheme();
 }
 StackPanel Group(string glyph,string text){var group=new StackPanel{Margin=new Thickness(2,8,2,8)};var caption=new StackPanel{Orientation=Orientation.Horizontal};caption.Children.Add(new TextBlock{Text=glyph,FontFamily=new FontFamily("Segoe Fluent Icons"),FontSize=16,Width=26});caption.Children.Add(Visuals.Label(text,14));body.Children.Add(new Expander{Header=caption,Content=group,IsExpanded=true,Margin=new Thickness(0,0,0,10)});return group;}
 public void ApplyTheme(){SuitePanels.Theme(this,surface,app.Store.Book.Theme);foreach(var button in themes){bool selected=(string)button.Tag==app.Store.Book.Theme;button.Background=selected?Visuals.Brush("#557F7FFF"):Visuals.Brush(Visuals.Dark(app.Store.Book.Theme)?"#3B3E47":"#E4E6ED");System.Windows.Automation.AutomationProperties.SetHelpText(button,selected?"Selecionado":"");}foreach(var button in Descendants<Button>(surface))button.Foreground=Foreground;}
 static System.Collections.Generic.IEnumerable<T> Descendants<T>(DependencyObject p) where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(p);i++){var c=VisualTreeHelper.GetChild(p,i);if(c is T value)yield return value;foreach(var child in Descendants<T>(c))yield return child;}}
 public void Present(){Show();Activate();if(SystemParameters.ClientAreaAnimation&&!SystemParameters.HighContrast)animation=new WindowRevealAnimation(this,true,()=>{});}
 public void Dismiss(bool animate=true){animation?.Dispose();void Finish(){closing=true;Close();}if(animate&&IsVisible&&SystemParameters.ClientAreaAnimation&&!SystemParameters.HighContrast)animation=new WindowRevealAnimation(this,false,Finish);else Finish();}
}
